@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#131b2b;--cream:#fff8e9;--orange:#ff744e;--yellow:#ffd35a;--blue:#77dce6;--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif;--body:'Manrope',sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#95c7d7;color:var(--ink);font-family:var(--body);user-select:none;-webkit-tap-highlight-color:transparent}.game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#a2d9e8}#game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.world-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(16,28,47,.34),transparent 21%,transparent 73%,rgba(16,28,47,.25)),linear-gradient(90deg,rgba(10,22,35,.12),transparent 23%,transparent 77%,rgba(10,22,35,.08));z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:78px;padding:0 4.7vw;display:flex;align-items:center;justify-content:space-between;color:#fff}.brand{display:flex;align-items:center;gap:12px;color:#fff;text-decoration:none}.brand-mark{height:27px;width:25px;display:flex;align-items:flex-end;gap:3px;transform:skew(-17deg)}.brand-mark i{display:block;width:6px;border-radius:4px 4px 1px 1px;background:var(--yellow)}.brand-mark i:nth-child(1){height:13px}.brand-mark i:nth-child(2){height:21px;background:var(--orange)}.brand-mark i:nth-child(3){height:27px;background:#fff}.brand-copy{font-weight:800;font-size:13px;letter-spacing:2px;line-height:1}.brand-copy span{display:block;letter-spacing:3.3px;font-size:9px;opacity:.72;margin-top:5px}.event-pill{font:500 10px var(--mono);letter-spacing:1.55px;color:rgba(255,255,255,.92);background:rgba(17,29,44,.24);border:1px solid rgba(255,255,255,.25);border-radius:30px;padding:10px 16px;backdrop-filter:blur(8px)}.event-pill b{font-weight:500;color:var(--yellow)}.event-divider{padding:0 8px;opacity:.44}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#aaffb0;margin-right:8px;box-shadow:0 0 9px #aaffb0}.sound-button{display:flex;align-items:center;gap:8px;border:1px solid rgba(255,255,255,.34);border-radius:30px;background:rgba(17,29,44,.22);color:white;padding:9px 13px;font:500 9px var(--mono);letter-spacing:1.1px;cursor:pointer}.sound-button #sound-icon{font-size:15px;color:var(--yellow)}.race-hud{position:absolute;z-index:2;inset:95px 4.7vw auto;display:none;align-items:flex-start;justify-content:space-between;pointer-events:none}.hud-panel{background:rgba(16,27,42,.79);backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,.17);color:#fff;border-radius:4px;box-shadow:0 8px 26px rgba(13,23,36,.12)}.timer-panel{width:181px;padding:13px 15px 11px}.hud-eyebrow{font:500 9px var(--mono);letter-spacing:1.6px;color:rgba(255,255,255,.65)}.tiny-flag{color:var(--orange);font-size:10px;margin-right:5px}.timer-value{font:700 38px/.98 var(--display);letter-spacing:1px;color:#fff;margin-top:6px}.timer-value span{font-size:23px;color:var(--yellow)}.timer-track{height:2px;background:rgba(255,255,255,.2);margin-top:11px}.timer-track i{height:100%;width:100%;display:block;background:var(--yellow);transition:width .1s linear}.lap-panel{position:absolute;left:50%;transform:translateX(-50%);padding:11px 20px 10px;text-align:center;min-width:190px}.lap-number{font:700 14px var(--display);color:var(--yellow);padding-left:6px}.lap-total{font:500 10px var(--mono);color:rgba(255,255,255,.48)}.lap-time{font:500 18px var(--mono);letter-spacing:1px;color:#fff;margin-top:5px}.best-label{font:400 8px var(--mono);color:rgba(255,255,255,.53);letter-spacing:1px;margin-top:4px}.best-label span{color:var(--yellow);padding-left:5px}.position-panel{color:#fff;text-align:right;padding:8px 0}.position-value{font:700 48px/.9 var(--display);margin-top:6px;text-shadow:0 2px 12px rgba(0,0,0,.2)}.position-value span{font-size:17px;color:var(--yellow);vertical-align:top;margin-left:2px}.position-note{font:500 8px var(--mono);letter-spacing:1.3px;color:rgba(255,255,255,.7);margin-top:7px}.track-map{position:absolute;right:0;top:94px;width:205px;padding:11px 13px 9px}.map-title{font:500 8px var(--mono);letter-spacing:1px;color:rgba(255,255,255,.7);display:flex;justify-content:space-between}.map-title span{color:#a7ffbd;font-size:7px}.track-map svg{display:block;width:100%;height:95px;margin:2px 0}.map-track-shadow{fill:none;stroke:rgba(0,0,0,.18);stroke-width:16;stroke-linecap:round}.map-track{fill:none;stroke:#e8e4d7;stroke-width:11;stroke-linecap:round}.map-center{fill:none;stroke:#788996;stroke-width:1;stroke-dasharray:3 3}.map-track path{stroke-linejoin:round}#map-player{fill:var(--orange);stroke:#fff;stroke-width:2;filter:drop-shadow(0 1px 4px rgba(0,0,0,.6));transition:cx .15s,cy .15s}.map-footer{display:flex;justify-content:space-between;font:400 7px var(--mono);color:rgba(255,255,255,.55);letter-spacing:.7px}.map-footer span{display:flex;align-items:center;gap:4px}.map-dot{width:5px;height:5px;border-radius:50%;background:var(--orange)}.race-bottom{position:absolute;z-index:2;left:4.7vw;right:4.7vw;bottom:30px;display:none;align-items:flex-end;justify-content:space-between;color:#fff}.controls-hint{display:flex;align-items:center;gap:4px}.keycap{width:25px;height:25px;border:1px solid rgba(255,255,255,.56);background:rgba(17,29,44,.3);border-radius:3px;display:flex;align-items:center;justify-content:center;font:500 10px var(--mono);color:#fff}.keycap.wide{width:25px}.keycap.space{width:60px;font-size:8px;letter-spacing:1px;margin-left:7px}.hint-copy{font:500 8px var(--mono);letter-spacing:.9px;color:rgba(255,255,255,.85);margin:0 9px 0 5px}.hint-separator{height:23px;width:1px;background:rgba(255,255,255,.35);margin:0 3px}.speed-cluster{width:190px;text-align:right}.speed-readout{font:700 55px/.85 var(--display);letter-spacing:1px;text-shadow:0 2px 12px rgba(0,0,0,.2)}.speed-readout small{font:500 9px var(--mono);letter-spacing:1px;color:rgba(255,255,255,.75);margin-left:5px}.speed-meter{height:3px;background:rgba(255,255,255,.35);margin:9px 0 7px}.speed-meter i{display:block;height:100%;width:0;background:var(--yellow);transition:width .12s}.boost-readout{font:500 8px var(--mono);letter-spacing:1.2px;color:rgba(255,255,255,.77)}.boost-readout .bolt{font-size:13px;color:var(--yellow);vertical-align:-1px;margin-right:4px}.boost-readout b{color:var(--yellow);font-weight:500;margin-left:4px}.center-notice{position:absolute;z-index:4;left:50%;top:42%;transform:translate(-50%,-50%);font:900 clamp(60px,12vw,150px)/.8 var(--display);letter-spacing:2px;color:#fff;text-shadow:0 5px 0 var(--orange),0 9px 28px rgba(0,0,0,.32);pointer-events:none}.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;background:rgba(14,24,39,.2);backdrop-filter:blur(1.3px)}.intro-card,.result-card{width:min(440px,calc(100vw - 32px));background:var(--cream);padding:30px 37px 20px;position:relative;box-shadow:0 24px 70px rgba(17,27,41,.28);border-radius:3px}.intro-card:before,.result-card:before{content:'';position:absolute;top:0;left:0;right:0;height:5px;background:linear-gradient(90deg,var(--orange) 0 37%,var(--yellow) 37% 70%,#67c7c7 70%)}.intro-kicker,.result-kicker{display:flex;align-items:center;gap:8px;font:500 8px var(--mono);letter-spacing:1.1px;color:#7e7b73}.sun-icon{font-size:15px;color:var(--orange)}.kicker-line{width:26px;height:1px;background:#d7d0c2}.title-lockup{position:relative;margin:17px 0 11px}.title-small{font:800 13px var(--display);letter-spacing:3.8px;color:#263447;margin-bottom:1px}.title-lockup h1{margin:0;color:#172237;font:900 67px/.78 var(--display);letter-spacing:-.7px;transform:scaleX(.95);transform-origin:left center}.title-lockup h1 span{color:var(--orange);font-size:69px;letter-spacing:-.5px}.title-badge{position:absolute;right:3px;top:15px;border:1px solid #d5ccba;border-radius:50%;width:62px;height:62px;display:grid;place-content:center;text-align:center;color:#8b826f;font:700 11px/1.03 var(--display);letter-spacing:1px;transform:rotate(11deg)}.intro-description{font-size:12px;line-height:1.65;color:#696d70;margin:17px 0 17px}.intro-description strong{font-weight:800;color:#263447}.intro-stats{display:flex;border-top:1px solid #e6dfd1;border-bottom:1px solid #e6dfd1;padding:11px 0;margin-bottom:15px}.intro-stats>div{flex:1;display:grid;grid-template-columns:20px auto;grid-template-rows:20px 11px;align-items:center;border-right:1px solid #e6dfd1;padding-left:9px}.intro-stats>div:last-child{border:0}.stat-icon{grid-row:1/3;color:var(--orange);font-size:14px}.intro-stats b{font:700 19px/.9 var(--display);color:#1e2a3c}.intro-stats small{font:500 7px var(--mono);letter-spacing:.9px;color:#8b8b83}.start-button{height:47px;width:100%;background:#ff744e;border:0;color:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 16px 0 19px;cursor:pointer;font:800 12px var(--body);letter-spacing:1.5px;box-shadow:0 4px 0 #d85639;transition:transform .15s,box-shadow .15s,background .15s}.start-button:hover{background:#ff6445;transform:translateY(-2px);box-shadow:0 6px 0 #d85639}.start-button:active{transform:translateY(2px);box-shadow:0 2px 0 #d85639}.start-button b{font-size:22px;font-weight:500}.intro-foot{display:flex;justify-content:center;align-items:center;gap:10px;margin-top:16px;font:500 7px var(--mono);letter-spacing:.6px;color:#85857d}.intro-foot b{color:#464d53;font-weight:500}.intro-foot i{width:3px;height:3px;background:var(--orange);border-radius:50%}.overlay-corner{position:absolute;color:rgba(255,255,255,.73);font:500 8px var(--mono);letter-spacing:1.5px}.corner-tl{top:26px;left:4.8vw}.corner-br{right:4.8vw;bottom:27px}.result-card{text-align:center;padding:35px 38px 21px}.result-kicker{justify-content:center}.result-kicker span{color:var(--orange)}.result-medal{margin:19px auto 10px;width:60px;height:60px;border-radius:50%;display:grid;place-items:center;background:#ffedc5;color:#ff994f;font-size:32px;box-shadow:inset 0 0 0 2px #f4d18c}.result-card h2{font:900 43px/.95 var(--display);margin:5px 0;color:#172237;letter-spacing:.5px}.result-card>p{font-size:11px;color:#73746f;margin:7px 0 19px}.result-stats{display:flex;padding:13px 0;border-top:1px solid #e4ddcf;border-bottom:1px solid #e4ddcf;margin-bottom:17px}.result-stats>div{flex:1;border-right:1px solid #e4ddcf;display:flex;flex-direction:column;gap:5px}.result-stats>div:last-child{border:0}.result-stats small{font:500 7px var(--mono);letter-spacing:.6px;color:#8a8982}.result-stats b{font:700 19px var(--display);color:#283247}.result-stats b i{font:500 7px var(--mono);font-style:normal;color:#86877f}.result-foot{font:500 7px var(--mono);letter-spacing:1px;color:#9b978d;margin-top:15px}.hidden{display:none!important}.toast{position:absolute;z-index:6;left:50%;bottom:105px;transform:translate(-50%,10px);opacity:0;background:#172337;color:#fff;padding:10px 15px;border-radius:3px;font:500 10px var(--mono);letter-spacing:.5px;transition:opacity .2s,transform .2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-controls{display:none}
@media (max-width:700px){.topbar{height:58px;padding:0 18px}.brand-copy{font-size:11px}.event-pill{font-size:8px;padding:8px 10px;letter-spacing:.9px}.sound-button{padding:8px 10px}.sound-label{display:none}.race-hud{inset:71px 14px auto}.timer-panel{width:128px;padding:9px 10px}.hud-eyebrow{font-size:7px}.timer-value{font-size:30px}.timer-value span{font-size:18px}.lap-panel{top:0;left:50%;min-width:130px;padding:8px 8px}.lap-time{font-size:14px}.best-label{font-size:6px}.position-panel{display:none}.track-map{top:80px;right:0;width:145px;padding:8px}.track-map svg{height:65px}.map-title{font-size:6px}.map-footer{font-size:6px}.race-bottom{left:16px;right:16px;bottom:110px}.controls-hint{display:none}.speed-cluster{width:130px}.speed-readout{font-size:42px}.speed-readout small{font-size:7px}.speed-meter{margin:6px 0}.boost-readout{font-size:7px}.intro-card{padding:25px 24px 17px;width:min(385px,calc(100vw - 34px))}.title-lockup h1{font-size:58px}.title-lockup h1 span{font-size:60px}.title-badge{width:54px;height:54px;font-size:9px;right:0}.intro-description{font-size:11px;margin:15px 0}.intro-stats{padding:9px 0;margin-bottom:13px}.intro-foot{font-size:6px;gap:7px}.corner-tl{left:18px;top:15px}.corner-br{right:18px;bottom:14px;font-size:6px}.mobile-controls{position:absolute;z-index:3;left:0;right:0;bottom:18px;height:78px;display:none;pointer-events:none}.mobile-controls button{pointer-events:auto;border:1px solid rgba(255,255,255,.38);color:#fff;background:rgba(17,29,44,.5);backdrop-filter:blur(7px);font:700 13px var(--mono);touch-action:none}.touch-steer{position:absolute;left:17px;width:55px;height:55px;border-radius:50%;font-size:30px!important}.touch-left{left:17px}.touch-steer#touch-right{left:80px}.touch-drift{position:absolute;right:88px;bottom:0;width:57px;height:44px;border-radius:25px;font-size:8px!important;letter-spacing:.5px}.touch-gas{position:absolute;right:17px;bottom:0;width:60px;height:60px;border-radius:50%;background:rgba(255,116,78,.78)!important}.touch-gas span{font-size:10px}.result-card{padding:30px 22px 18px}.result-stats small{font-size:6px}.result-card h2{font-size:38px}}
@media (max-height:650px){.intro-card{transform:scale(.88)}.topbar{height:60px}.race-hud{top:72px}.race-bottom{bottom:18px}.track-map{top:83px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.166.1/build/three.module.js';

const canvas = document.querySelector('#game-canvas');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#9dd4e4');
scene.fog = new THREE.FogExp2('#9dd4e4', 0.00165);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, 0.1, 1200);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

scene.add(new THREE.HemisphereLight('#fff1d2', '#477b61', 2.2));
const sun = new THREE.DirectionalLight('#fff0ce', 3.2);
sun.position.set(-80, 130, -70);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -130; sun.shadow.camera.right = 130; sun.shadow.camera.top = 130; sun.shadow.camera.bottom = -130;
sun.shadow.bias = -0.00015;
scene.add(sun);

const mat = (color, roughness = .86, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const materials = {
  grass: mat('#62a967'), road: mat('#424a51'), curbRed: mat('#f56d53'), curbWhite: mat('#fff0d6'),
  line: mat('#f9efce'), tree: mat('#286f5c'), tree2: mat('#3c9168'), trunk: mat('#805544'),
  wood: mat('#b77443'), cream: mat('#fff2d6'), orange: mat('#fa704e'), yellow: mat('#ffd45e'), blue: mat('#64c7d2'),
  dark: mat('#263445'), tire: mat('#20232b'), metal: mat('#b8c5c6', .4, { metalness: .4 }),
};

const ground = new THREE.Mesh(new THREE.PlaneGeometry(1200, 1200), materials.grass);
ground.rotation.x = -Math.PI / 2; ground.position.y = -0.55; ground.receiveShadow = true; scene.add(ground);

const controlPoints = [
  [0, 0, 67], [43, 0, 61], [72, 0, 34], [77, 0, 0], [62, 0, -37],
  [34, 0, -61], [-4, 0, -67], [-43, 0, -58], [-70, 0, -34], [-75, 0, 3],
  [-59, 0, 38], [-31, 0, 60]
].map(([x,y,z]) => new THREE.Vector3(x, y, z));
const trackCurve = new THREE.CatmullRomCurve3(controlPoints, true, 'catmullrom', .25);
const trackLength = trackCurve.getLength();
const roadWidth = 13.5;
const samples = 720;
const pointAt = (u) => trackCurve.getPointAt(((u % 1) + 1) % 1);
const tangentAt = (u) => trackCurve.getTangentAt(((u % 1) + 1) % 1).normalize();
const rightAt = (u) => { const t = tangentAt(u); return new THREE.Vector3(t.z, 0, -t.x); };

function ribbon(inner, outer, material, yOffset = 0) {
  const vertices = [], indices = [];
  for (let i = 0; i <= samples; i++) {
    const u = i / samples, p = pointAt(u), right = rightAt(u);
    for (const side of [inner, outer]) vertices.push(p.x + right.x * side, p.y + yOffset, p.z + right.z * side);
    if (i < samples) { const a = i * 2; indices.push(a, a+1, a+2, a+1, a+3, a+2); }
  }
  const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3)); g.setIndex(indices); g.computeVertexNormals();
  const mesh = new THREE.Mesh(g, material); mesh.receiveShadow = true; mesh.castShadow = false; scene.add(mesh); return mesh;
}
ribbon(-roadWidth / 2 - 1.5, roadWidth / 2 + 1.5, materials.curbWhite, -.02);
ribbon(-roadWidth / 2, roadWidth / 2, materials.road, .02);
ribbon(-roadWidth / 2 - .7, -roadWidth / 2, materials.curbRed, .045);
ribbon(roadWidth / 2, roadWidth / 2 + .7, materials.curbRed, .045);

// Crisp center dashes and two fine edge guides.
for (let i = 0; i < 145; i++) {
  const u = i / 145, p = pointAt(u), t = tangentAt(u), r = rightAt(u);
  if (i % 2 === 0) {
    const dash = new THREE.Mesh(new THREE.BoxGeometry(.13, .025, 1.15), materials.line);
    dash.position.set(p.x, .065, p.z); dash.rotation.y = Math.atan2(t.x, t.z); scene.add(dash);
  }
}

// Starting grid, checker stripe and landmark gantry.
function box(parent, name, size, material, pos, rotation = [0,0,0]) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(...size), material); m.name = name;
  m.position.set(...pos); m.rotation.set(...rotation); m.castShadow = true; m.receiveShadow = true; parent.add(m); return m;
}
const startU = .008, startP = pointAt(startU), startT = tangentAt(startU), startAngle = Math.atan2(startT.x, startT.z);
for (let i = 0; i < 14; i++) {
  const lateral = -roadWidth / 2 + (i + .5) * roadWidth / 14;
  const r = rightAt(startU); const tile = new THREE.Mesh(new THREE.BoxGeometry(roadWidth / 14, .035, 1.5), mat(i % 2 ? '#202731' : '#fff4df'));
  tile.position.set(startP.x + r.x * lateral, .09, startP.z + r.z * lateral); tile.rotation.y = startAngle; scene.add(tile);
}
const gantry = new THREE.Group(); gantry.position.copy(pointAt(.035)); gantry.position.y = 0; gantry.rotation.y = Math.atan2(tangentAt(.035).x, tangentAt(.035).z); scene.add(gantry);
box(gantry,'arch-leg',[.55,7,.55],materials.dark,[-7.6,3.5,0]); box(gantry,'arch-leg',[.55,7,.55],materials.dark,[7.6,3.5,0]);
box(gantry,'arch-beam',[16,1.05,.75],materials.orange,[0,7,0]); box(gantry,'arch-face',[7.6,1.05,.12],materials.dark,[0,7,-.44]);
const gantryText = box(gantry,'sign',[5.3,.35,.08],materials.yellow,[0,7,-.53]);
for (let i=0;i<6;i++) { const lamp = new THREE.Mesh(new THREE.SphereGeometry(.22,12,8), mat(i<3?'#fff5ce':'#ffb3a0',.2,{emissive:i<3?'#ffcf55':'#ff4e3b',emissiveIntensity:1.6})); lamp.position.set(-5.4+i*2.16,7,.5); gantry.add(lamp); }

// Low-poly island scenery: palms, rounded pines, flower tufts, and pastel billboards.
const treeGeo = new THREE.ConeGeometry(1, 2.5, 7);
const treeTopGeo = new THREE.ConeGeometry(1.35, 2.4, 7);
const trunkGeo = new THREE.CylinderGeometry(.19,.28,1.8,7);
const treeMeshes = [];
for (let i = 0; i < 180; i++) {
  const u = (i * .61803398875) % 1, p = pointAt(u), tangent = tangentAt(u), right = rightAt(u);
  const side = i % 2 ? 1 : -1;
  const offset = roadWidth / 2 + 8 + ((i * 19) % 22);
  const wobble = Math.sin(i * 42.12) * 3.4;
  const pos = p.clone().addScaledVector(right, side * offset).addScaledVector(tangent, wobble);
  const group = new THREE.Group(); group.position.set(pos.x,0,pos.z);
  const scale = .72 + (i * 37 % 55) / 100;
  const trunk = new THREE.Mesh(trunkGeo, materials.trunk); trunk.position.y=.9; trunk.scale.setScalar(scale); trunk.castShadow=true; group.add(trunk);
  const crownMat = i % 3 === 0 ? materials.tree2 : materials.tree;
  const crown = new THREE.Mesh(treeTopGeo,crownMat); crown.position.y=2.65*scale; crown.scale.setScalar(scale); crown.castShadow=true; group.add(crown);
  const crown2 = new THREE.Mesh(treeGeo,crownMat); crown2.position.set(.05,3.45*scale,.04); crown2.scale.setScalar(scale*.7); crown2.castShadow=true; group.add(crown2);
  scene.add(group); treeMeshes.push(group);
}

// Distant island silhouettes and sunset puffs.
for (let i=0;i<28;i++) {
  const a=i/28*Math.PI*2, radius=175+(i%4)*15, h=18+(i*17%34);
  const hill = new THREE.Mesh(new THREE.ConeGeometry(25+(i%3)*8,h,7),mat(i%2?'#70998a':'#83aa91'));
  hill.position.set(Math.cos(a)*radius,h/2-3,Math.sin(a)*radius); hill.rotation.y=i*1.72; scene.add(hill);
}
for(let i=0;i<14;i++){
  const cloud=new THREE.Group(), x=(i*67%240)-120, z=(i*89%210)-105;
