  mapPlayer.setAttribute('cx',marker.x);mapPlayer.setAttribute('cy',marker.y);
  $('#map-checkpoint').textContent=`CHECKPOINT ${String(Math.floor((state.distance/trackLength%1)*4)+1).padStart(2,'0')}`;
